Future<void> main() async {
  PWAInstall().setup(installCallback: () => debugPrint('APP INSTALLED!'));
  runApp(MaterialApp(home: Scaffold(body: ElevatedButton(
    onPressed: () {
      if (PWAInstall().installPromptEnabled) {
        PWAInstall().promptInstall_();
      }
    },
    child: Text('Install PWA'),
  ))));
}
